-- 0179: aṣl from every book, batch 01 — each book's own statement (read by its profile; Lane in English), verbatim with
-- block + page and a plain English line; primary = the meaning most books share. Quotes checked against their blocks.
-- aslmb_01: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- ابو
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ابو:khalil_kitab_ayn', 'ابو', '7370d09fb98ef8b4969e38c4be', 'أَبَوْتُ الرّجلَ آبوه، إذا كنت له أباً', 'to be a father to someone', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_abw44p1', NULL, NULL, 'blk_kay_abw_h', 0, NULL, 'Marker: «يقال … إذا». Reading: father. Primary: father — 2 of 3 books (al-Khalīl blk_kay_abw_h; Lane blk_lane_6875b5d8148d6776). Other readings: raising and feeding: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ابو:lane_lexicon', 'ابو', '7370d09fb98ef8b4969e38c4be', 'I became a father.', 'I became a father', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_440d521f2418b86b', '10', NULL, 'blk_lane_6875b5d8148d6776', 0, NULL, 'Marker: first sense A1. Reading: father.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: raising and feeding. Differs from the main reading (father).', updated_at = datetime('now') WHERE id = 'ASL:ابو:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:ابو:khalil_kitab_ayn' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'ابو' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:ابو:khalil_kitab_ayn' AND status <> 'rejected');
